void SetTextLanguageEnglish(bool english) noexcept { gEnglish=english; }
bool TextLanguageEnglish() noexcept { return gEnglish; }

const char* LocalizedText(const char* english) noexcept {
    if (!english||gEnglish) return english;
    for (const LocalizedString& entry:kStrings)
        if (std::strcmp(entry.english,english)==0) return entry.koreanUtf8;
    const std::size_t length=std::strlen(english);
    if (length!=0 && english[length-1]=='.')
        for (const LocalizedString& entry:kStrings)
            if (std::strlen(entry.english)==length-1
                && std::strncmp(entry.english,english,length-1)==0)
                return entry.koreanUtf8;
    return english;
}

const LocalizedString* RuntimeStrings(std::uint16_t& count) noexcept {
    count=static_cast<std::uint16_t>(sizeof(kStrings)/sizeof(kStrings[0]));
    return kStrings;
}

